public static void main(String[] args) {
	Scanner sc = new Scanner(System.in);
	long x = sc.nextLong();
	sc.close();
	long y = 0;
	if (x % 10 == 0) {
		y = x / 10;
	} else {
		if (x > 0) {
			y = x / 10 + 1;
		} else {
			y = x / 10;
		}
	}

	System.out.println(y);
}

